import { defineConfig } from "@wagmi/cli";
import { foundry } from "@wagmi/cli/plugins";

// ABIs of the six Solvers contracts, read from contracts/out (built by scripts/generate.mjs first).
// Never edit src/generated by hand: run `pnpm --filter @solvers/contracts-client generate`.
export default defineConfig({
  out: "src/generated/abis.ts",
  plugins: [
    foundry({
      project: "../../contracts",
      artifacts: "out",
      include: [
        "SolversRegistry.sol/**",
        "SolversLicense.sol/**",
        "SolversCredits.sol/**",
        "SolversReviews.sol/**",
        "SolversEscrow.sol/**",
        "SolversStaking.sol/**",
      ],
      forge: { build: false, path: process.env.FORGE_BIN ?? "forge" },
    }),
  ],
});
